backward.source:
def chosen(value):
    def second(arg):
        return not arg
    def first(arg):
        return second(arg)
    return first(value)

diamond.source:
def chosen(value):
    def first(arg):
        return leaf(arg)
    def second(arg):
        return not leaf(arg)
    def leaf(arg):
        return arg
    return first(value) or second(value)

forward.source:
def chosen(value):
    def first(arg):
        return second(arg)
    def second(arg):
        return not arg
    return first(value)

guarded-cycle.source:
def chosen(value):
    def first(arg):
        if arg:
            return second(False)
        return False
    def second(arg):
        if arg:
            return True
        return first(False)
    return first(value)

local-shadow.source:
def chosen(value):
    def first(arg):
        second = False
        return second(arg)
    def second(arg):
        return arg
    return first(value)

nonlocal-rebind.source:
def chosen(value):
    def first(arg):
        nonlocal second
        second = False
        return arg
    def second(arg):
        return not arg
    return first(value)

outer-capture.source:
def chosen(value):
    def first():
        return value
    return first()

outer-rebind.source:
def chosen(value):
    def first(arg):
        return second(arg)
    def second(arg):
        return not arg
    second = False
    return first(value)

parameter-shadow.source:
def chosen(value):
    def first(second):
        return second(True)
    def second(arg):
        return not arg
    return first(value)

unresolved-global.source:
def other(value):
    return not value
def chosen(value):
    def first(arg):
        return other(arg)
    return first(value)
